-- gen615: 27 zone cambiate, 55 tessere
-- a4cc27660ac7257ed997b80fd9b2e405 (964731) → 8799c5d2ae02533bd7aee1cb2f06ce5e (986015)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '8799c5d2ae02533bd7aee1cb2f06ce5e' as combacia
from kv_store where key like 'tmp:gen615:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen615:p%')
where key='app:jsx:src'
  and md5(value) = 'a4cc27660ac7257ed997b80fd9b2e405'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen615:p%') = '8799c5d2ae02533bd7aee1cb2f06ce5e';

update kv_store set value = '{"len":986015,"ver":"gen-6.15"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '8799c5d2ae02533bd7aee1cb2f06ce5e';

delete from kv_store where key like 'tmp:gen615:p%';
